CREATE TABLE IF NOT EXISTS tenants (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(180) NOT NULL,slug VARCHAR(100) NOT NULL UNIQUE,status VARCHAR(30) NOT NULL DEFAULT 'active',created_at DATETIME NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,name VARCHAR(160) NOT NULL,email VARCHAR(190) NOT NULL,password_hash VARCHAR(255) NOT NULL,role VARCHAR(30) NOT NULL DEFAULT 'agent',status VARCHAR(30) NOT NULL DEFAULT 'active',mfa_secret_enc TEXT NULL,mfa_enabled TINYINT(1) NOT NULL DEFAULT 0,created_at DATETIME NOT NULL,UNIQUE KEY uq_user_email(email),KEY ix_users_tenant(tenant_id),CONSTRAINT fk_users_tenant FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS tenant_meta (tenant_id BIGINT UNSIGNED PRIMARY KEY,waba_id VARCHAR(100) NULL,phone_number_id VARCHAR(100) NULL,verify_token VARCHAR(190) NULL,access_token_enc TEXT NULL,app_secret_enc TEXT NULL,meta_app_id VARCHAR(100) NULL,updated_at DATETIME NULL,UNIQUE KEY uq_meta_phone(phone_number_id),CONSTRAINT fk_meta_tenant FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS media_assets (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,phone_number_id VARCHAR(100) NOT NULL,meta_media_id VARCHAR(190) NOT NULL,mime_type VARCHAR(120) NOT NULL,media_type VARCHAR(30) NOT NULL,filename VARCHAR(255) NOT NULL,created_at DATETIME NOT NULL,UNIQUE KEY uq_media_asset(tenant_id,meta_media_id),KEY ix_media_tenant(tenant_id,id),CONSTRAINT fk_media_asset_tenant FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS contacts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,name VARCHAR(190) NOT NULL,phone VARCHAR(32) NOT NULL,consent_status VARCHAR(30) NOT NULL DEFAULT 'unknown',consent_source VARCHAR(255) NULL,consent_at DATETIME NULL,opted_out_at DATETIME NULL,created_at DATETIME NOT NULL,UNIQUE KEY uq_contact_phone(tenant_id,phone),KEY ix_contacts_tenant(tenant_id),CONSTRAINT fk_contacts_tenant FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS conversations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,contact_id BIGINT UNSIGNED NOT NULL,phone_number_id VARCHAR(100) NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'open',assignee_id BIGINT UNSIGNED NULL,unread_count INT NOT NULL DEFAULT 0,last_inbound_at DATETIME NULL,last_message_at DATETIME NULL,last_message_preview VARCHAR(255) NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,KEY ix_conv_tenant(tenant_id,status),KEY ix_conv_contact(contact_id),CONSTRAINT fk_conv_tenant FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,CONSTRAINT fk_conv_contact FOREIGN KEY(contact_id) REFERENCES contacts(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS messages (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,conversation_id BIGINT UNSIGNED NOT NULL,direction VARCHAR(10) NOT NULL,type VARCHAR(40) NOT NULL,body MEDIUMTEXT NULL,wamid VARCHAR(190) NULL,media_id VARCHAR(190) NULL,media_filename VARCHAR(255) NULL,media_mime VARCHAR(120) NULL,status VARCHAR(40) NOT NULL,created_at DATETIME NOT NULL,UNIQUE KEY uq_message_wamid(tenant_id,wamid),KEY ix_msg_conversation(tenant_id,conversation_id,id),CONSTRAINT fk_msg_tenant FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,CONSTRAINT fk_msg_conversation FOREIGN KEY(conversation_id) REFERENCES conversations(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS templates (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,name VARCHAR(512) NOT NULL,language VARCHAR(20) NOT NULL,category VARCHAR(30) NOT NULL,body MEDIUMTEXT NOT NULL,status VARCHAR(40) NOT NULL DEFAULT 'PENDING',meta_id VARCHAR(100) NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,UNIQUE KEY uq_template(tenant_id,name,language),CONSTRAINT fk_tpl_tenant FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS quick_replies (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,name VARCHAR(120) NOT NULL,body MEDIUMTEXT NOT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,UNIQUE KEY uq_quick_reply(tenant_id,name),KEY ix_quick_reply_tenant(tenant_id),CONSTRAINT fk_quick_reply_tenant FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS campaigns (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,name VARCHAR(190) NOT NULL,template_id BIGINT UNSIGNED NULL,status VARCHAR(30) NOT NULL DEFAULT 'draft',scheduled_at DATETIME NULL,started_at DATETIME NULL,completed_at DATETIME NULL,created_at DATETIME NOT NULL,KEY ix_campaign_tenant(tenant_id,status,scheduled_at),CONSTRAINT fk_campaign_tenant FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS campaign_recipients (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,campaign_id BIGINT UNSIGNED NOT NULL,contact_id BIGINT UNSIGNED NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'pending',wamid VARCHAR(190) NULL,error TEXT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,UNIQUE KEY uq_campaign_contact(campaign_id,contact_id),KEY ix_campaign_queue(tenant_id,status,campaign_id),CONSTRAINT fk_recipient_tenant FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,CONSTRAINT fk_recipient_campaign FOREIGN KEY(campaign_id) REFERENCES campaigns(id) ON DELETE CASCADE,CONSTRAINT fk_recipient_contact FOREIGN KEY(contact_id) REFERENCES contacts(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS api_keys (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,name VARCHAR(120) NOT NULL,key_hash CHAR(64) NOT NULL UNIQUE,key_prefix VARCHAR(24) NOT NULL,scopes VARCHAR(255) NOT NULL,created_at DATETIME NOT NULL,revoked_at DATETIME NULL,CONSTRAINT fk_key_tenant FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS tenant_webhooks (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,url VARCHAR(2048) NOT NULL,secret_enc TEXT NOT NULL,events VARCHAR(500) NOT NULL,active TINYINT(1) NOT NULL DEFAULT 1,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,UNIQUE KEY uq_tenant_hook(tenant_id),CONSTRAINT fk_hook_tenant FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS webhook_outbox (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,event_key VARCHAR(100) NOT NULL,event_type VARCHAR(80) NOT NULL,payload MEDIUMTEXT NOT NULL,attempts INT NOT NULL DEFAULT 0,next_attempt_at DATETIME NULL,status VARCHAR(24) NOT NULL DEFAULT 'pending',last_error TEXT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,KEY ix_outbox_ready(status,next_attempt_at),KEY ix_outbox_tenant(tenant_id,id),CONSTRAINT fk_outbox_tenant FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS webhook_events (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,event_hash CHAR(64) NOT NULL,payload MEDIUMTEXT NOT NULL,created_at DATETIME NOT NULL,UNIQUE KEY uq_event_hash(tenant_id,event_hash),CONSTRAINT fk_event_tenant FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS idempotency_keys (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,idem_key VARCHAR(190) NOT NULL,response_json MEDIUMTEXT NOT NULL,created_at DATETIME NOT NULL,UNIQUE KEY uq_idempotency(tenant_id,idem_key),CONSTRAINT fk_idem_tenant FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS audit_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NULL,action VARCHAR(100) NOT NULL,details JSON NULL,ip VARCHAR(45) NULL,created_at DATETIME NOT NULL,KEY ix_audit_tenant(tenant_id,id),CONSTRAINT fk_audit_tenant FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS login_attempts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,email VARCHAR(190) NOT NULL,ip VARCHAR(45) NOT NULL,created_at DATETIME NOT NULL,KEY ix_login_attempt(email,ip,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
